<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use DigiForgePrintifyConnector\Preparation\{PublicationContract,PreparationService,MutationFence,VersionedMutationHost,ProviderReceipt,OrderReadModel,WebhookContract,WorkflowCoordinator,WorkflowPanel};
require_once __DIR__.'/../fixtures/printify-connector/stage34/companion-test-bootstrap.php';
final class PrintifyCompanionBatch4Test extends TestCase {
 private function fixture():array{return (require __DIR__.'/../fixtures/printify-connector/batch4/fixture.php')();}
 public function testOfflineWorkflowContractsExist():void{self::assertTrue(class_exists(PublicationContract::class));self::assertTrue(class_exists(WebhookContract::class));self::assertTrue(class_exists(OrderReadModel::class));}
 public function testPublicationIsScopedImmutableAndNeverPublishedByAcknowledgement():void{[$s,$input,$e,$ctx]=$this->fixture();$i=(new PreparationService())->publish($s,$input,$e,$ctx);self::assertSame('PRODUCT_PUBLISH',$i->operation);self::assertFalse($i->jsonSerialize()['external_execution_authorized']);self::assertSame('PUBLISH_PENDING',PublicationContract::reconcile($i->prepared(),[],200)['state']);$ctx['logical_reference']='another-alias';$other=(new PreparationService())->publish($s,$input,$e,$ctx);self::assertSame($i->duplicateKey,$other->duplicateKey);}
 /** @dataProvider invalidPublication */
 public function testPublicationRejectsWrongIdentityAndStaleEvidence(string $target,string $key,mixed $value):void{[$s,$input,$e,$ctx]=$this->fixture();if($target==='input')$input[$key]=$value;else $e[$key]=$value;$this->expectException(InvalidArgumentException::class);(new PreparationService())->publish($s,$input,$e,$ctx);}
 public static function invalidPublication():array{return [['input','product_id','other'],['input','flags',['title'=>1]],['input','flags',['url'=>'https://untrusted.test']],['e','shop_key','standard_pod'],['e','provider_shop_id','999'],['e','sales_channel','disconnected'],['e','sales_channel','shopify'],['e','connected',false],['e','eligible',false],['e','product_version',2],['e','authorization_revision',2],['e','approver_role','ADMIN'],['e','approval_receipt',null]];}
 public function testPublishReadbackNeverFabricatesChannelCertification():void{[$s,$input,$e,$ctx]=$this->fixture();$r=PublicationContract::prepare($s,$input,$e);self::assertSame('PUBLISH_PENDING',PublicationContract::readback($r,['id'=>$input['product_id'],'shop_id'=>(int)$s->providerShopId,'is_locked'=>true])['state']);self::assertSame('UNKNOWN',PublicationContract::reconcile($r,[],504)['state']);$this->expectException(InvalidArgumentException::class);PublicationContract::readback($r,['id'=>'wrong','shop_id'=>(int)$s->providerShopId,'is_locked'=>false]);}
 public function testPublicationUsesExistingOneShotCoreAndReceiptSequenceRules():void{[$s,$input,$e,$ctx]=$this->fixture();require_once __DIR__.'/../fixtures/printify-connector/batch2/SyntheticMutationCore.php';$c=new SyntheticMutationCore();$h=new VersionedMutationHost($c);$f=new MutationFence($h);$i=(new PreparationService())->publish($s,$input,$e,$ctx);self::assertIsArray($f->register($i));self::assertIsArray($f->reserve($i));self::assertInstanceOf(WP_Error::class,$f->reserve($i));$r=$c->receipt($i);$late=$r;$late['sequence']=2;$late['receipt_hash']=ProviderReceipt::hash($late);self::assertInstanceOf(WP_Error::class,$h->acceptReceipt($i,$late));self::assertSame('METADATA_RECONCILED',$h->acceptReceipt($i,$r)['state']);self::assertSame(1,$c->receiptCount);self::assertSame('PUBLISH_PENDING',ProviderReceipt::validate($i,$r)['state']);$r['body']=['published'=>true];$r['receipt_hash']=ProviderReceipt::hash($r);self::assertInstanceOf(WP_Error::class,$h->acceptReceipt($i,$r));}
 public function testOrderProjectionIsTypedPrivateAndRequiresProofLineage():void{[$s,,,, $order,$lineage]=$this->fixture();$o=OrderReadModel::fromProvider($s,$order,$lineage,str_repeat('a',64));self::assertInstanceOf(OrderReadModel::class,$o);$data=$o->jsonSerialize();self::assertSame('PENDING',$data['status']);self::assertFalse($data['external_execution_authorized']);self::assertStringNotContainsString('Private Street',json_encode($o));$lineage[0]['proof_receipt']=null;$blocked=OrderReadModel::fromProvider($s,$order,$lineage,str_repeat('a',64))->jsonSerialize();self::assertContains('PERSONALIZATION_PROOF_MISSING',$blocked['blockers']);self::assertTrue($blocked['manual_review_required']);}
 /** @dataProvider invalidOrders */
 public function testOrderValidationRejectsMalformedFields(string $field,mixed $value):void{[$s,,,, $order,$lineage]=$this->fixture();$keys=explode('.',$field);$v=&$order;foreach($keys as $k)$v=&$v[$k];$v=$value;$this->expectException(InvalidArgumentException::class);OrderReadModel::fromProvider($s,$order,$lineage,str_repeat('a',64));}
 public static function invalidOrders():array{return [['shop_id',999],['id','https://bad'],['address_to.country','ZZ'],['address_to.address1',[]],['address_to.email','invalid'],['line_items.0.quantity',0],['line_items.0.variant_id',true],['line_items',[]],['status','<script>']];}
 public function testUnknownStatusAndMissingLineageAreManualReviewOnly():void{[$s,,,, $order]=$this->fixture();$order['status']='future-state';$o=OrderReadModel::fromProvider($s,$order,[],str_repeat('a',64))->jsonSerialize();self::assertSame('UNKNOWN',$o['status']);self::assertContains('PRODUCT_LINEAGE_MISSING',$o['blockers']);self::assertTrue($o['manual_review_required']);}
 public function testDocumentedHmacAndShopValidation():void{[$s,,,,,, $event,$secret]=$this->fixture();$raw=json_encode($event);$sig='sha256='.hash_hmac('sha256',$raw,$secret);$v=WebhookContract::verify($s,$raw,$sig,$secret,time());self::assertSame($event['id'],$v['event_id']);self::assertTrue($v['authoritative_readback_required']);self::assertFalse($v['business_transition_authorized']);self::assertArrayNotHasKey('body',$v);$this->expectException(InvalidArgumentException::class);WebhookContract::verify($s,$raw,$sig.'0',$secret,time());}
 /** @dataProvider invalidEvents */
 public function testSignedButInvalidEventDenied(string $field,mixed $value):void{[$s,,,,,, $event,$secret]=$this->fixture();$keys=explode('.',$field);$v=&$event;foreach($keys as $k)$v=&$v[$k];$v=$value;$raw=json_encode($event);$sig='sha256='.hash_hmac('sha256',$raw,$secret);$this->expectException(InvalidArgumentException::class);WebhookContract::verify($s,$raw,$sig,$secret,time());}
 public static function invalidEvents():array{return [['resource.data.shop_id',999],['resource.type','product'],['type','order:delete-all'],['id','bad'],['created_at','2000-01-01 00:00:00+00:00'],['resource.id','https://bad']];}
 public function testCoreOwnedWorkflowDeduplicationConflictAndOrdering():void{[$s,,,, $order,$lineage,$event,$secret]=$this->fixture();require_once __DIR__.'/../fixtures/printify-connector/batch4/SyntheticWorkflowCore.php';$core=new SyntheticWorkflowCore();$w=new WorkflowCoordinator($core);$o=OrderReadModel::fromProvider($s,$order,$lineage,str_repeat('a',64));self::assertSame('RECORDED',$w->ingestOrder($s,1,$o)['disposition']);self::assertSame('DUPLICATE',$w->ingestOrder($s,1,$o)['disposition']);$raw=json_encode($event);$sig='sha256='.hash_hmac('sha256',$raw,$secret);self::assertSame('RECORDED',$w->webhook($s,1,$raw,$sig)['disposition']);self::assertSame('DUPLICATE',$w->webhook($s,1,$raw,$sig)['disposition']);$event['type']='order:updated';$raw=json_encode($event);$sig='sha256='.hash_hmac('sha256',$raw,$secret);self::assertSame('CONFLICT',$w->webhook($s,1,$raw,$sig)['disposition']);$event['id']='aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee';$event['created_at']=gmdate('Y-m-d H:i:sP',time()-100);$raw=json_encode($event);$sig='sha256='.hash_hmac('sha256',$raw,$secret);self::assertSame('OUT_OF_ORDER',$w->webhook($s,1,$raw,$sig)['disposition']);self::assertStringContainsString('Manual review',WorkflowPanel::render($w,$s,1));}
 public function testUnavailableRevokedOrIncompatibleWorkflowCoreDenies():void{[$s,,,, $order,$lineage]=$this->fixture();$o=OrderReadModel::fromProvider($s,$order,$lineage,str_repeat('a',64));self::assertInstanceOf(WP_Error::class,(new WorkflowCoordinator())->ingestOrder($s,1,$o));require_once __DIR__.'/../fixtures/printify-connector/batch4/SyntheticWorkflowCore.php';foreach(['revoked','wrong_shop','wrong_version','storage_failure']as $fault){$c=new SyntheticWorkflowCore();$c->fault=$fault;self::assertInstanceOf(WP_Error::class,(new WorkflowCoordinator($c))->ingestOrder($s,1,$o));}}
 public function testStopAndLockStillDenyPublication():void{[$s,$input,$e,$ctx]=$this->fixture();require_once __DIR__.'/../fixtures/printify-connector/batch2/SyntheticMutationCore.php';foreach(['stop_all','external_lock','revoked']as $fault){$c=new SyntheticMutationCore();$c->fault=$fault;$i=(new PreparationService())->publish($s,$input,$e,$ctx);self::assertInstanceOf(WP_Error::class,(new MutationFence(new VersionedMutationHost($c)))->register($i));}}
 public function testNewReadReceiptDoesNotChangeOrderBusinessIdentity():void{[$s,,,, $o,$lineage]=$this->fixture();$a=OrderReadModel::fromProvider($s,$o,$lineage,str_repeat('a',64));$b=OrderReadModel::fromProvider($s,$o,$lineage,str_repeat('b',64));self::assertSame($a->jsonSerialize()['content_hash'],$b->jsonSerialize()['content_hash']);}
 public function testCoreMustExplicitlySupportPublicationOwnerAdmission():void{[$s,$input,$e,$ctx]=$this->fixture();require_once __DIR__.'/../fixtures/printify-connector/batch2/SyntheticMutationCore.php';$generic=new class implements DigiForgePrintifyConnector\Preparation\MutationCoreInterface {public function version():string{return '1.0.0';}public function exchange(array $q):array|WP_Error{return (new SyntheticMutationCore())->exchange($q);}};$i=(new PreparationService())->publish($s,$input,$e,$ctx);self::assertInstanceOf(WP_Error::class,(new VersionedMutationHost($generic))->authorize($i));}
 public function testForgedValidFormatSignatureAndChangedRawBytesRejected():void{[$s,,,,,, $event,$secret]=$this->fixture();$raw=json_encode($event);foreach(['sha256='.str_repeat('0',64),'sha256='.hash_hmac('sha256',$raw.' ',$secret)]as $sig){try{WebhookContract::verify($s,$raw,$sig,$secret,time());self::fail('Forged HMAC accepted');}catch(InvalidArgumentException){self::assertTrue(true);}}}
 public function testRejectedWebhookEvidenceAndOrderExternalConflictAreReadOnly():void{[$s,,,, $o,$lineage,$event,$secret]=$this->fixture();require_once __DIR__.'/../fixtures/printify-connector/batch4/SyntheticWorkflowCore.php';$c=new SyntheticWorkflowCore();$w=new WorkflowCoordinator($c);self::assertInstanceOf(WP_Error::class,$w->webhook($s,1,json_encode($event),'sha256='.str_repeat('0',64)));self::assertSame('REJECTED',$w->snapshot($s,1)['items'][0]['disposition']);$w->ingestOrder($s,1,OrderReadModel::fromProvider($s,$o,$lineage,str_repeat('a',64)));$o['id']='duplicate_external_order';self::assertSame('CONFLICT',$w->ingestOrder($s,1,OrderReadModel::fromProvider($s,$o,$lineage,str_repeat('a',64)))['disposition']);$json=$w->export($s,1);self::assertIsString($json);self::assertStringNotContainsString('Private Street',$json);self::assertStringNotContainsString('synthetic@example.invalid',$json);}

 public function testPersonalizationProofCannotBeReusedAcrossDistinctLineItems():void{[$s,,,,$order,$lineage]=$this->fixture();$second=$order['line_items'][0];$second['id']='second_line_item';$order['line_items'][]=$second;$v=OrderReadModel::fromProvider($s,$order,$lineage,str_repeat('a',64))->jsonSerialize();self::assertContains('PRODUCT_LINEAGE_MISSING',$v['blockers']);self::assertNull($v['items'][1]['proof_receipt']);}

 public function testOrderCannotBeIngestedUnderAnotherShopBinding():void{[$s,,,,$o,$lineage]=$this->fixture();$model=OrderReadModel::fromProvider($s,$o,$lineage,str_repeat('a',64));$other=new DigiForge\Connector\Printify\ShopBinding(3,'standard_pod',99003,'99004','test',7,new DigiForge\Connector\Printify\CredentialReference(99003),str_repeat('b',64),2000000000);require_once __DIR__.'/../fixtures/printify-connector/batch4/SyntheticWorkflowCore.php';$c=new SyntheticWorkflowCore();self::assertInstanceOf(WP_Error::class,(new WorkflowCoordinator($c))->ingestOrder($other,1,$model));self::assertCount(0,$c->records);}

 public function testWorkflowViewRejectsCrossShopRowsEvenWhenOuterScopeMatches():void{[$s,,,,$o,$lineage]=$this->fixture();require_once __DIR__.'/../fixtures/printify-connector/batch4/SyntheticWorkflowCore.php';$c=new SyntheticWorkflowCore();$w=new WorkflowCoordinator($c);$w->ingestOrder($s,1,OrderReadModel::fromProvider($s,$o,$lineage,str_repeat('a',64)));$c->fault='view_wrong_scope';self::assertInstanceOf(WP_Error::class,$w->snapshot($s,1));}

